describe('Multi-step Form Progress Indicator', () => {
  beforeEach(() => {
    cy.visit('/multi-step-form');
  });

  it('should display progress indicator showing current step', () => {
    // Verify initial progress indicator shows step 1
    cy.get('[data-testid="progress-indicator"]').should('be.visible');
    cy.get('[data-testid="progress-step-1"]').should('have.class', 'active');
    cy.get('[data-testid="progress-step-2"]').should('not.have.class', 'active');
    cy.get('[data-testid="progress-step-3"]').should('not.have.class', 'active');

    // Fill step 1 form and proceed to step 2
    cy.get('[data-testid="input-name"]').type('John Doe');
    cy.get('[data-testid="input-email"]').type('john@example.com');
    cy.get('[data-testid="btn-next"]').click();

    // Verify progress indicator updates to step 2
    cy.get('[data-testid="progress-step-1"]').should('have.class', 'completed');
    cy.get('[data-testid="progress-step-2"]').should('have.class', 'active');
    cy.get('[data-testid="progress-step-3"]').should('not.have.class', 'active');

    // Fill step 2 form and proceed to step 3
    cy.get('[data-testid="input-phone"]').type('555-1234');
    cy.get('[data-testid="btn-next"]').click();

    // Verify progress indicator updates to step 3
    cy.get('[data-testid="progress-step-1"]').should('have.class', 'completed');
    cy.get('[data-testid="progress-step-2"]').should('have.class', 'completed');
    cy.get('[data-testid="progress-step-3"]').should('have.class', 'active');
  });

  it('should update progress indicator when navigating backwards', () => {
    // Navigate to step 2
    cy.get('[data-testid="input-name"]').type('Jane Smith');
    cy.get('[data-testid="input-email"]').type('jane@example.com');
    cy.get('[data-testid="btn-next"]').click();

    // Verify on step 2
    cy.get('[data-testid="progress-step-2"]').should('have.class', 'active');

    // Navigate back to step 1
    cy.get('[data-testid="btn-back"]').click();

    // Verify progress indicator reverts to step 1
    cy.get('[data-testid="progress-step-1"]').should('have.class', 'active');
    cy.get('[data-testid="progress-step-2"]').should('not.have.class', 'active');
    cy.get('[data-testid="progress-step-2"]').should('not.have.class', 'completed');
  });

  it('should display progress percentage correctly', () => {
    // Verify initial progress is 33% (1 of 3 steps)
    cy.get('[data-testid="progress-percentage"]').should('contain', '33%');

    // Move to step 2
    cy.get('[data-testid="input-name"]').type('Test User');
    cy.get('[data-testid="input-email"]').type('test@example.com');
    cy.get('[data-testid="btn-next"]').click();

    // Verify progress is 66% (2 of 3 steps)
    cy.get('[data-testid="progress-percentage"]').should('contain', '66%');

    // Move to step 3
    cy.get('[data-testid="input-phone"]').type('555-5678');
    cy.get('[data-testid="btn-next"]').click();

    // Verify progress is 100% (3 of 3 steps)
    cy.get('[data-testid="progress-percentage"]').should('contain', '100%');
  });

  it('should maintain progress indicator state on form validation error', () => {
    // Attempt to proceed without filling required fields
    cy.get('[data-testid="btn-next"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Verify progress indicator remains on step 1
    cy.get('[data-testid="progress-step-1"]').should('have.class', 'active');
    cy.get('[data-testid="progress-step-2"]').should('not.have.class', 'active');
  });
});
